import{_ as e,o as a,c as s,S as n}from"./chunks/framework.f15d8f8c.js";const y=JSON.parse('{"title":"FAQs","description":"","frontmatter":{},"headers":[],"relativePath":"faqs/index.md","filePath":"faqs/index.md"}'),t={name:"faqs/index.md"},o=n(`<h1 id="faqs" tabindex="-1">FAQs <a class="header-anchor" href="#faqs" aria-label="Permalink to &quot;FAQs&quot;">​</a></h1><h2 id="common-faqs" tabindex="-1">Common faqs <a class="header-anchor" href="#common-faqs" aria-label="Permalink to &quot;Common faqs&quot;">​</a></h2><div class="language-html"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#A6ACCD;">Q. Can i change my authorized domain later?</span></span></code></pre></div><p>Answer: No, authorization for a domain cannot be changed once issued. To use a new domain for your website, website must be hosted on authorized domain/sub domain and use nginx reverse proxy to set new domain. <a href="/introduction/hestia-reverse-proxy.html">HestiaCP Reverse proxy website</a> and <a href="/introduction/aapanel-reverse-proxy.html">Aapanel Reverse proxy website</a></p><div class="language-html"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#A6ACCD;">Q. IP Limit is set to 1 but i can only connect to one node and sometime all disconnect?</span></span></code></pre></div><p>Answer: Probabily you are using a CDN for the server address(node). CDN mostly have more than 1 ips attached to them, you must extract the real user ip from the CDN header and by doing so can you get the real online user ip. Without it your online ip count will be more than 1 hence connect disconnect since limit is exceeded. This can be done by using nginx reverse proxy on the backend server. <a href="/backend/proxy.html">Check Here</a></p><div class="language-html"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#A6ACCD;">Q. Can an expired service(plan) be renewd?</span></span></code></pre></div><p>Answer: Yes, when a service expires you will see a renew button.</p><div class="language-html"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#A6ACCD;">Q. Why does service traffic reset after expire even when traffic is not used up ?.</span></span></code></pre></div><p>Answer: By default all services traffic will reset when expired even if unuused. You can change that in admin Settings -&gt; General -&gt; Services -&gt; Reset Service and Service Renew.</p><div class="language-html"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#A6ACCD;">Q. Can a service expired time be calculated from the time of first connection?</span></span></code></pre></div><p>Answer: Yes. Set that in admin Settings -&gt; General -&gt; Services -&gt; Service Expire.</p><div class="language-html"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#A6ACCD;">Q. How to setup relay(Transit) from Server A to server B with XMPlus backend?</span></span></code></pre></div><p>Answer: Install on both backends XMPlus-Relay, make sure you are able to connect to each server independently. Edit server settings in admin panel, Server A select XMPlus for transit type and select Server B as transit server. Save and wait for about 1-2 minutes to take effect or manually restart backend.</p><p>NB: If you want to use reality tcp as a transit (Server B), use flow: <code>xtls-rprx-vision-udp443</code> only this can be able to work, else use <code>xtls-rprx-vision</code> if not using for transit.</p><div class="language-html"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#A6ACCD;">Q. How to write blocking rules?</span></span></code></pre></div><p>Answer: you can define 1 rule per input on frontend admin panel. The rule can be in regex format or plain format.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#A6ACCD;">#Regex format:  </span></span>
<span class="line"><span style="color:#A6ACCD;">(.+\\.|^)(360|so)\\.(cn|com) </span></span>
<span class="line"><span style="color:#A6ACCD;">   </span></span>
<span class="line"><span style="color:#A6ACCD;">#Plain format : </span></span>
<span class="line"><span style="color:#A6ACCD;">google.com</span></span>
<span class="line"><span style="color:#A6ACCD;">   </span></span>
<span class="line"><span style="color:#A6ACCD;">#IP Format: </span></span>
<span class="line"><span style="color:#A6ACCD;">127.0.0.1</span></span></code></pre></div><p>You can also add your rules to backend rulelist in <code>/etc/XMPlus/rulelist</code> and uncomment RuleListPath: in config.yml and restart backend.</p><div class="language-html"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#A6ACCD;">Q. How can i translate panel to other language?</span></span></code></pre></div><p>Answer: Make a copy of the default english template file in /i18n/en_US.php in your website server directory. Translate the value part and save in the langauge you want. Add the name in all available translation files. Example: file name sv_SE.php for Swedish langauge and in the file and all other files add <code>&quot;sv_SE&quot; =&gt; &quot;Swedish (SE)&quot;,</code></p>`,21),l=[o];function i(r,p,c,d,h,u){return a(),s("div",null,l)}const g=e(t,[["render",i]]);export{y as __pageData,g as default};
